import sys

def main():
    data = sys.stdin.read().split()
    pos = 0
    T = data[pos]
    pos += 1
    N = int(data[pos])
    pos += 1
    bags = []
    for _ in range(N):
        A = int(data[pos])
        pos += 1
        strings = data[pos:pos + A]
        pos += A
        bags.append(strings)

    L = len(T)
    INF = float('inf')
    dp = [dict() for _ in range(N + 1)]
    dp[0] = {0: 0}

    for i in range(1, N + 1):
        prev = dp[i - 1]
        cur = {}
        for p, cost in prev.items():
            cur[p] = min(cur.get(p, INF), cost)
        for p, cost in prev.items():
            for s in bags[i - 1]:
                np = p + len(s)
                if np <= L and T[p:np] == s:
                    new_cost = cost + 1
                    if new_cost < cur.get(np, INF):
                        cur[np] = new_cost
        dp[i] = cur

    ans = dp[N].get(L, -1)
    if ans == INF:
        print(-1)
    else:
        print(ans)

if __name__ == "__main__":
    main()
