import sys

def solve():
    data = sys.stdin.read().split()
    n = int(data[0])
    strings = data[1:1 + n]
    m = max(len(s) for s in strings)
    T = [list('*' * n) for _ in range(m)]
    for i, s in enumerate(strings):
        col = n - i  # 1-based column index in T rows
        for j, ch in enumerate(s):
            T[j][col - 1] = ch
    for j in range(m):
        while T[j] and T[j][-1] == '*':
            T[j].pop()
        sys.stdout.write(''.join(T[j]) + '\n')

if __name__ == '__main__':
    solve()
