import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    strings = data[1:1 + N]
    M = max(len(s) for s in strings)
    out = []
    for j in range(M):
        chars = []
        for i in range(N):
            if j < len(strings[i]):
                chars.append(strings[i][j])
            else:
                chars.append('*')
        # Trim trailing '*'
        while chars and chars[-1] == '*':
            chars.pop()
        out.append(''.join(chars))
    sys.stdout.write('\n'.join(out) + '\n')

if __name__ == '__main__':
    main()
