import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    N = int(data[idx]); idx += 1
    items = []
    for _ in range(N):
        a = int(data[idx]); b = int(data[idx+1]); idx += 2
        items.append((a, b))

    total = sum(b for _, b in items)
    if total % 3 != 0:
        print(-1)
        return
    target = total // 3

    from functools import lru_cache

    # DP over index i (next person to process), with state = (team1 sum, team2 sum, team3 sum)
    # We process people one by one; each person is assigned to a team.
    # cost = number of people assigned to a different team than original.
    # We need exactly target for each team.
    @lru_cache(maxsize=None)
    def dp(i, s1, s2, s3):
        if i == N:
            if s1 == target and s2 == target and s3 == target:
                return 0
            return -1  # unreachable
        a, b = items[i]
        best = -1
        # try placing person i into team 1
        if s1 + b <= target:
            res = dp(i+1, s1+b, s2, s3)
            if res != -1:
                cand = res + (0 if 1 == a else 1)
                if best == -1 or cand < best:
                    best = cand
        # team 2
        if s2 + b <= target:
            res = dp(i+1, s1, s2+b, s3)
            if res != -1:
                cand = res + (0 if 2 == a else 1)
                if best == -1 or cand < best:
                    best = cand
        # team 3
        if s3 + b <= target:
            res = dp(i+1, s1, s2, s3+b)
            if res != -1:
                cand = res + (0 if 3 == a else 1)
                if best == -1 or cand < best:
                    best = cand
        return best

    ans = dp(0, 0, 0, 0)
    if ans == -1:
        print(-1)
    else:
        print(ans)

solve()
